input.sparql:
SELECT DISTINCT ?point ?class WHERE {
  ?point a ?class .
  ?point ref:hasTimeseriesId ?ts .
  FILTER(str(?class) != "brick:Point")
}

SELECT ?p ?class ?label ?tsid WHERE {
  ?z a ?zclass .
  FILTER(str(?zlabel) = "Perimeter_top_ZN_4")
  ?z rdfs:label ?zlabel .
  ?p brick:isPointOf ?z .
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

SELECT ?p ?class ?label ?tsid WHERE {
  ?p a brick:OccupancyCount .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p brick:isPointOf ?z }
}

SELECT ?p ?tsid ?ext WHERE {
  ?p a brick:Occupancy_Sensor .
  FILTER(str(?p) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z05.Occupancy_Sensor")
  ?p ref:hasTimeseriesId ?tsid .
}
